{"source":"import csv
import json
import sys
from decimal import Decimal, ROUND_HALF_UP, getcontext

getcontext().prec = 40

def main():
    input_path = sys.argv[1]
    with open(input_path, "r", encoding="utf-8") as f:
        rows = list(csv.DictReader(f))

    aggregated = {}
    total = Decimal(0)
    total = total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    for row in rows:
        status = row.get("status", "")
        if status is None:
            continue
        if status.strip().casefold() != "paid":
            continue

        category = row.get("category") or ""
        normalized_category = " ".join(category.split()).casefold()
        if not normalized_category:
            normalized_category = "uncategorized"

        amount_str = (row.get("amount") or "").strip()
        amount = Decimal(amount_str).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        aggregated[normalized_category] = aggregated.get(normalized_category, Decimal(0)) + amount
        total += amount

    total = total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    result = {
        "categories": [
            {"category": cat, "total": str(aggregated[cat].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))}
            for cat in sorted(aggregated)
        ],
        "total": str(total),
    }

    json.dump(result, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")

if __name__ == "__main__":
    main()
"}

